import bpy,numpy as np,json,hashlib
from pathlib import Path
R=Path(__file__).resolve().parents[1];m=json.loads((R/'receipts/build_r3.json').read_text());p=Path(m['source']);assert hashlib.sha256(p.read_bytes()).hexdigest()==m['source_sha256'];a=np.load(m['array_path']);assert hashlib.sha256(Path(m['array_path']).read_bytes()).hexdigest()==m['array_sha256'];bpy.ops.wm.open_mainfile(filepath=str(p));s=bpy.context.scene;ob=s.objects['Plastic / native height / shared top-right seam'];mesh=ob.data
v=np.empty(a['local_position_m'].size,'f4');mesh.vertices.foreach_get('co',v);assert np.array_equal(v,a['local_position_m'].ravel());ix=np.empty(a['triangles'].size,'i4');mesh.loops.foreach_get('vertex_index',ix);assert np.array_equal(ix,a['triangles'].ravel());nn=np.empty(a['loop_normals'].size,'f4');mesh.attributes['IntendedNormalField'].data.foreach_get('vector',nn);assert np.array_equal(nn,a['loop_normals'].ravel());assert mesh.attributes['IntendedNormalField'].domain=='CORNER';assert not ob.modifiers and tuple(ob.scale)==(1.,1.,1.)
nd=mesh.materials[0].node_tree.nodes;assert any(n.type=='VECT_TRANSFORM' and n.vector_type=='NORMAL' and n.convert_from=='OBJECT' and n.convert_to=='WORLD' for n in nd)
for name in ['ChartLocal','NormalField']:assert name in s.view_layers[0].aovs and any(n.type=='OUTPUT_AOV' and n.aov_name==name for n in nd)
assert s.camera.name==m['camera'] and s.cycles.samples==1 and not s.cycles.use_adaptive_sampling and not s.cycles.use_denoising;r={'fresh_reopen':True,'positions_and_indices_exact':True,'all_float32_corner_normals_bit_exact':True,'object_world_normal_transform_explicit':True,'AOV_and_sampling_verified':True,'source_sha256':m['source_sha256'],'no_render':True};(R/'receipts/preflight_r3.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(r),flush=True)
